input.sparql:
SELECT ?zone ?zoneName WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?zoneName .
  FILTER (LCASE(str(?zoneName)) LIKE '%basement%' || str(?zoneName) = "Perimeter_top_ZN_3")
}

SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
  ?z a brick:Room .
} LIMIT 1

SELECT ?sensor ?label ?zone ?ref ?tsid WHERE {
  ?sensor a brick:Occupancy_Sensor .
  OPTIONAL { ?sensor rdfs:label ?label }
  ?zone brick:hasSubComponent ?sensor .
  OPTIONAL { ?ref ref:hasTimeseriesId ?tsid ; ref:isReferenceOf ?sensor }
}

SELECT ?room ?label ?sensor ?tsid WHERE {
  ?room a brick:Room .
  OPTIONAL { ?room rdfs:label ?label }
  ?room brick:hasSubComponent ?sensor .
  ?ref ref:hasTimeseriesId ?tsid ; ref:isReferenceOf ?sensor .
} LIMIT 5

SELECT ?room ?zone ?zlabel WHERE {
  ?zone a brick:HVAC_Zone .
  ?zone brick:hasSubComponent ?room .
  OPTIONAL { ?zone rdfs:label ?zlabel }
} LIMIT 5

